B.afl=new A.ax(B.ZX,"Nu vindem, nu \xeenchiriem \u0219i nu comercializ\u0103m datele tale personale.")
B.a01=new A.R(61326,"MaterialIcons",null,!1)
B.af7=new A.ax(B.a01,"Detaliile bancare sunt colectate de Stripe \u0219i nu sunt stocate pe serverele noastre.")
